it('says exactly what the old code said, for every moved message in both languages', function (array $case) {
    [$code, $locale, $subject, $body, $values] = $case;
    $definition = app(TemplateCatalog::class)->get($code);
    expect($definition)->not->toBeNull();
    [$firstSubject, $firstBody] = $definition->defaults[$locale];
    $render = app(TemplateRenderer::class);

    expect($render->render($firstBody, $values, $definition->multiline))->toBe($body);
    if ($subject !== null) {
        expect($render->singleLine($render->render((string) $firstSubject, $values)))->toBe($subject);
    }
})->with(fn () => array_map(fn (array $c) => [$c], migratedExpected()));

it('has English and Bangla words for every message a module declares, using only variables it declares', function () {
    foreach (app(TemplateCatalog::class)->all() as $code => $definition) {
        foreach (['en', 'bn'] as $locale) {
            expect(array_key_exists($locale, $definition->defaults))->toBeTrue("{$code} has no {$locale} words");
            [$subject, $body] = $definition->defaults[$locale];
            expect(trim($body))->not->toBe('');
            if ($definition->channel === 'email') {
                expect(trim((string) $subject))->not->toBe('');
            }
            $render = app(TemplateRenderer::class);
            foreach (array_filter([$subject, $body]) as $text) {
                expect(array_diff($render->names($text), $definition->variables))->toBe([], "{$code} ({$locale}) uses an undeclared variable");
                expect($render->hasStrayBraces($text))->toBeFalse();
            }
        }
        expect($definition->multiline)->each->toBeIn($definition->variables);
    }
});
